// FACET: adjust extraction to your channel's inbound payload shape.
const b = items[0].json.body || items[0].json;
const p = b.payload || b;
if (p.fromMe === true) return [];
const from = String(p.from || p.chatId || p.sender || '').replace('@c.us','');
const text = (p.body || p.text || p.message || '').toString().trim();
if (!from) throw new Error('inbound missing sender');
return [{ json: { from, text, receivedAt: new Date().toISOString() } }];

const inc = $node['Parse'].json;
const stored = $node['Load Context'].json || {};
const transcript = Array.isArray(stored.transcript) ? stored.transcript.slice(-6) : [];
const capture = (stored.capture && typeof stored.capture === 'object') ? stored.capture : {};

let kb = '';
try { const k = $node['Knowledge Lookup'].json; kb = Array.isArray(k.chunks) ? k.chunks.join('\n\n') : (k.text || JSON.stringify(k)); } catch (e) {}
if (!kb) kb = '(knowledge base unavailable)';

const system = [
  `{{FACET_SYSTEM_PROMPT}}`,
  ``,
  `Answer ONLY from KNOWLEDGE. If it's not there, say a human will follow up and set needs_human true. Never invent facts, prices, or policies.`,
  `Keep replies short and plain text. Respond with STRICT JSON only, no code fence:`,
  `{"reply": string, "capture": object, "needs_human": boolean}`,
  `Put any structured details you gather into capture; merge with what's known.`,
  ``,
  `KNOWLEDGE:\n${kb}`,
  ``,
  `CAPTURED SO FAR: ${JSON.stringify(capture)}`
].join('\n');

const messages = [{ role: 'system', content: system }];
for (const t of transcript) messages.push({ role: t.role === 'assistant' ? 'assistant' : 'user', content: String(t.content || '') });
messages.push({ role: 'user', content: inc.text });

return [{ json: { messages, from: inc.from, text: inc.text, captureSoFar: capture, transcript } }];

const from = $node['Build Prompt'].json.from;
const captureSoFar = $node['Build Prompt'].json.captureSoFar || {};
let raw = '';
try { const r = items[0].json; raw = r.choices?.[0]?.message?.content || r.content || r.message?.content || ''; } catch (e) {}
let parsed = null;
if (raw) {
  let s = String(raw).trim().replace(/^```(json)?/i,'').replace(/```$/,'').trim();
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a >= 0 && b > a) { try { parsed = JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
}
if (!parsed || typeof parsed.reply !== 'string') {
  return [{ json: { from, reply: 'Thanks \u2014 someone will get back to you shortly.', capture: captureSoFar, needs_human: true, degraded: true } }];
}
const capture = Object.assign({}, captureSoFar, (parsed.capture && typeof parsed.capture === 'object') ? parsed.capture : {});
return [{ json: { from, reply: parsed.reply.trim(), capture, needs_human: parsed.needs_human === true, degraded: false } }];
